files.content:
.root {
  width: min(100%, 64rem);
  height: 38rem;
  min-height: 30rem;
  border-radius: var(--moduix-radius-lg);
  box-shadow: var(--moduix-shadow-sm);
}

.brand {
  display: flex;
  align-items: center;
  gap: var(--moduix-spacing-2);
  min-width: 0;
  color: inherit;
  font-weight: var(--moduix-weight-semibold);
  text-decoration: none;
}

.brandMark {
  display: grid;
  flex: none;
  place-items: center;
  width: var(--moduix-size-sm);
  height: var(--moduix-size-sm);
  border-radius: var(--moduix-radius-sm);
  background-color: var(--moduix-color-primary);
  color: var(--moduix-color-primary-foreground);
  font-size: var(--moduix-text-xs);
}

.workspaceMark {
  display: grid;
  flex: none;
  place-items: center;
  width: var(--moduix-size-sm);
  height: var(--moduix-size-sm);
  border-radius: var(--moduix-radius-sm);
  background-color: var(--moduix-color-muted);
  color: var(--moduix-color-foreground);
  font-size: var(--moduix-text-xs);
  font-weight: var(--moduix-weight-semibold);
}

.workspaceMenu {
  width: 11rem;
  min-width: 11rem;
  max-width: 11rem;
}

.content {
  display: grid;
  gap: var(--moduix-spacing-6);
  min-height: 100%;
  padding: var(--moduix-spacing-6);
}

.header {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--moduix-spacing-4);
}

.header h1,
.header p {
  margin: 0;
}

.header h1 {
  margin-block-start: var(--moduix-spacing-1);
  font-size: var(--moduix-text-2xl);
  line-height: var(--moduix-line-height-text-2xl);
}

.eyebrow {
  color: var(--moduix-color-muted-foreground);
  font-size: var(--moduix-text-sm);
  font-weight: var(--moduix-weight-medium);
}

.header .description {
  margin-block-start: var(--moduix-spacing-2);
  color: var(--moduix-color-muted-foreground);
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--moduix-spacing-4);
}

.metric {
  display: grid;
  gap: var(--moduix-spacing-2);
  justify-items: center;
  text-align: center;
}

.metric span {
  color: var(--moduix-color-muted-foreground);
  font-size: var(--moduix-text-sm);
}

.metric strong {
  font-size: var(--moduix-text-3xl);
  line-height: var(--moduix-line-height-text-3xl);
}

.activity {
  align-self: start;
}

.activityBody {
  display: grid;
  gap: var(--moduix-spacing-1);
}

.activityBody strong {
  color: var(--moduix-color-foreground);
}

@media (width < 40rem) {
  .content {
    padding: var(--moduix-spacing-4);
  }

  .metrics {
    grid-template-columns: 1fr;
  }
}
